namespace workbench {

    /**
     * Query tabs: several queries open side by side on one repository's Query page (ExecPlan
     * .agent/execplan-query-tabs-g2.md). This module holds the tab state, its localStorage copy and the tab row's
     * DOM; query.ts wires it to the editor, the form and the result controller. Every state operation returns a new
     * state object, so a change is a change of identity.
     */
    export namespace queryTabs {

        export interface QueryTabRun {
            /** 'ready': the query finished while another tab was shown, so the row count is not known yet. */
            status: 'done' | 'error' | 'ready';
            rowCount: number | null;
            total: number | null;
            elapsedMs: number | null;
            at: number;
            /** The result as saved in this browser (queryStream SavedResultSnapshot), shown again by a later page. */
            saved?: SavedResult | null;
        }

        /**
         * What a later page needs to show a tab's result again: the row store that holds its rows (none for an answer
         * or an empty result), the rows it held when saved, and the request that continues it. The rest of the
         * snapshot is the result renderer's (queryStream.ts, SavedResultSnapshot).
         */
        export interface SavedResult {
            storeId: string | null;
            rows: number;
            savedAt: number;
            request: string;
            url: string;
            [key: string]: any;
        }

        export interface QueryTab {
            id: string;
            /** An explicit name (the saved query's); null shows a title derived from the query text. */
            title: string | null;
            /** Opened from, or saved as, a saved query: the tab shows a bookmark. */
            saved: boolean;
            query: string;
            queryLn: string;
            /** The text changed since the tab last ran, or since it was opened from or saved as a saved query. */
            dirty: boolean;
            lastRun: QueryTabRun | null;
        }

        export interface QueryTabsState {
            version: 1;
            activeId: string;
            tabs: QueryTab[];
        }

        /** The subset of window.localStorage the store needs; a missing or throwing storage keeps the state in memory. */
        export interface StorageLike {
            getItem(key: string): string | null;
            setItem(key: string, value: string): void;
            removeItem?(key: string): void;
        }

        export interface Store {
            get(): QueryTabsState;
            set(next: QueryTabsState): void;
            subscribe(listener: (state: QueryTabsState) => void): () => void;
        }

        export const MAX_TABS = 20;
        export const UNTITLED = 'Untitled query';
        const TITLE_LENGTH = 40;
        export const STORAGE_PREFIX = 'rdf4j.workbench.query.tabs.v2:';

        /**
         * The tabs of a repository on a server for a user (workbench.workspace scopes: the server's digest, the user,
         * the repository), the same in every browser session.
         */
        export function storageKey(scope: { digest: string; user: string; repositoryId: string }): string {
            return STORAGE_PREFIX + JSON.stringify([scope.digest || '', scope.user || '', scope.repositoryId || '']);
        }

        let idCounter = 0;

        function nextId(existing: QueryTab[]): string {
            let id: string;
            do {
                idCounter += 1;
                id = 't' + Date.now().toString(36) + (idCounter % 1296).toString(36)
                    + Math.floor(Math.random() * 1296).toString(36);
            } while (existing.some(tab => tab.id === id));
            return id;
        }

        /**
         * The first line of the query that says something: not blank, not a comment, not a PREFIX or BASE
         * declaration; whitespace collapsed and cut to 40 characters. An empty query is 'Untitled query'.
         */
        export function deriveTitle(query: string): string {
            const lines = String(query || '').split(/\r?\n/);
            let candidate = '';
            for (let i = 0; i < lines.length; i++) {
                const line = lines[i].replace(/\s+/g, ' ').trim();
                if (!line || line.charAt(0) === '#' || /^(prefix|base)\b/i.test(line)) {
                    continue;
                }
                candidate = line;
                break;
            }
            if (!candidate) {
                return UNTITLED;
            }
            return candidate.length > TITLE_LENGTH ? candidate.substring(0, TITLE_LENGTH - 1) + '…' : candidate;
        }

        export function titleOf(tab: QueryTab): string {
            return tab && tab.title ? tab.title : deriveTitle(tab ? tab.query : '');
        }

        export function isDerivedTitle(tab: QueryTab): boolean {
            return !(tab && tab.title);
        }

        export function newTab(query?: string, options?: { title?: string; saved?: boolean; queryLn?: string },
                               existing?: QueryTab[]): QueryTab {
            const settings = options || {};
            return {
                id: nextId(existing || []),
                title: settings.title || null,
                saved: !!settings.saved,
                query: String(query || ''),
                queryLn: settings.queryLn || 'SPARQL',
                dirty: false,
                lastRun: null
            };
        }

        export function emptyState(): QueryTabsState {
            const tab = newTab('');
            return { version: 1, activeId: tab.id, tabs: [tab] };
        }

        function isRun(value: any): value is QueryTabRun {
            return !!value && typeof value === 'object'
                && (value.status === 'done' || value.status === 'error' || value.status === 'ready');
        }

        function sanitizeTab(value: any, existing: QueryTab[]): QueryTab {
            if (!value || typeof value !== 'object' || typeof value.query !== 'string') {
                return null;
            }
            const id = typeof value.id === 'string' && value.id && !existing.some(tab => tab.id === value.id)
                ? value.id : nextId(existing);
            const run = isRun(value.lastRun) ? value.lastRun : null;
            return {
                id: id,
                title: typeof value.title === 'string' && value.title ? value.title : null,
                saved: !!value.saved,
                query: value.query,
                queryLn: typeof value.queryLn === 'string' && value.queryLn ? value.queryLn : 'SPARQL',
                dirty: !!value.dirty,
                lastRun: run ? {
                    status: run.status,
                    rowCount: typeof run.rowCount === 'number' ? run.rowCount : null,
                    total: typeof run.total === 'number' ? run.total : null,
                    elapsedMs: typeof run.elapsedMs === 'number' ? run.elapsedMs : null,
                    at: typeof run.at === 'number' ? run.at : 0,
                    saved: isSavedResult(run.saved) ? run.saved : null
                } : null
            };
        }

        function isSavedResult(value: any): boolean {
            return !!value && typeof value === 'object'
                && (value.storeId === null || typeof value.storeId === 'string' && value.storeId.indexOf('rows-') === 0)
                && typeof value.rows === 'number' && value.rows >= 0 && Math.floor(value.rows) === value.rows
                && typeof value.request === 'string' && typeof value.url === 'string'
                && typeof value.savedAt === 'number' && typeof value.view === 'string';
        }

        /** The saved result of a tab's last run, or null. */
        export function savedResult(tab: QueryTab): SavedResult | null {
            return tab && tab.lastRun && tab.lastRun.saved || null;
        }

        /**
         * Records the saved result of a tab's last run. A run reported as ready (it ended out of sight) learns its row
         * count from it; a tab without a run gets one, as of when the result was saved.
         */
        export function saveRun(state: QueryTabsState, id: string, saved: SavedResult | null): QueryTabsState {
            const tab = findTab(state, id);
            if (!tab) {
                return state;
            }
            const run: QueryTabRun = tab.lastRun ? Object.assign({}, tab.lastRun)
                : { status: 'done', rowCount: null, total: null, elapsedMs: null, at: saved ? saved.savedAt : Date.now() };
            run.saved = saved;
            if (saved && run.rowCount === null && run.status !== 'error') {
                run.rowCount = saved.rows;
            }
            return update(state, id, { lastRun: run });
        }

        /** The stored JSON as a state, or null when it is not one this version understands. */
        export function parseState(json: string): QueryTabsState | null {
            if (!json) {
                return null;
            }
            let parsed: any;
            try {
                parsed = JSON.parse(json);
            } catch (error) {
                return null;
            }
            if (!parsed || typeof parsed !== 'object' || parsed.version !== 1 || !Array.isArray(parsed.tabs)) {
                return null;
            }
            const tabs: QueryTab[] = [];
            for (let i = 0; i < parsed.tabs.length && tabs.length < MAX_TABS; i++) {
                const tab = sanitizeTab(parsed.tabs[i], tabs);
                if (tab) {
                    tabs.push(tab);
                }
            }
            if (!tabs.length) {
                return null;
            }
            const active = tabs.some(tab => tab.id === parsed.activeId) ? parsed.activeId : tabs[0].id;
            return { version: 1, activeId: active, tabs: tabs };
        }

        export function serializeState(state: QueryTabsState): string {
            return JSON.stringify({ version: 1, activeId: state.activeId, tabs: state.tabs });
        }

        export function activeTab(state: QueryTabsState): QueryTab {
            return findTab(state, state.activeId) || state.tabs[0] || null;
        }

        export function findTab(state: QueryTabsState, id: string): QueryTab {
            const matches = state.tabs.filter(tab => tab.id === id);
            return matches.length ? matches[0] : null;
        }

        /** The tab whose text equals the given text, ignoring surrounding whitespace. */
        export function findByQuery(state: QueryTabsState, query: string): QueryTab {
            const wanted = String(query || '').trim();
            const matches = state.tabs.filter(tab => tab.query.trim() === wanted);
            return matches.length ? matches[0] : null;
        }

        /** Append a tab and make it active; at the limit the state is returned unchanged. */
        export function open(state: QueryTabsState, tab: QueryTab): QueryTabsState {
            if (state.tabs.length >= MAX_TABS) {
                return state;
            }
            return { version: 1, activeId: tab.id, tabs: state.tabs.concat([tab]) };
        }

        /**
         * Remove a tab. Closing the active tab activates the one to its right, else the one to its left; closing
         * the last tab leaves one fresh empty tab.
         */
        export function close(state: QueryTabsState, id: string): QueryTabsState {
            const index = indexOf(state, id);
            if (index < 0) {
                return state;
            }
            const tabs = state.tabs.slice(0, index).concat(state.tabs.slice(index + 1));
            if (!tabs.length) {
                return emptyState();
            }
            let activeId = state.activeId;
            if (activeId === id) {
                activeId = tabs[Math.min(index, tabs.length - 1)].id;
            }
            return { version: 1, activeId: activeId, tabs: tabs };
        }

        export function activate(state: QueryTabsState, id: string): QueryTabsState {
            if (state.activeId === id || indexOf(state, id) < 0) {
                return state;
            }
            return { version: 1, activeId: id, tabs: state.tabs };
        }

        export function update(state: QueryTabsState, id: string, patch: Partial<QueryTab>): QueryTabsState {
            const index = indexOf(state, id);
            if (index < 0) {
                return state;
            }
            const current = state.tabs[index];
            const next: QueryTab = {
                id: current.id,
                title: patch.title !== undefined ? patch.title : current.title,
                saved: patch.saved !== undefined ? patch.saved : current.saved,
                query: patch.query !== undefined ? patch.query : current.query,
                queryLn: patch.queryLn !== undefined ? patch.queryLn : current.queryLn,
                dirty: patch.dirty !== undefined ? patch.dirty : current.dirty,
                lastRun: patch.lastRun !== undefined ? patch.lastRun : current.lastRun
            };
            const tabs = state.tabs.slice();
            tabs[index] = next;
            return { version: 1, activeId: state.activeId, tabs: tabs };
        }

        /** Record the editor's text; a changed text makes the tab dirty until it runs or is saved again. */
        export function setQuery(state: QueryTabsState, id: string, query: string): QueryTabsState {
            const tab = findTab(state, id);
            const text = String(query || '');
            if (!tab || tab.query === text) {
                return state;
            }
            return update(state, id, { query: text, dirty: true });
        }

        /** Records how a tab's run went; the result it saved stays unless the run says otherwise. */
        export function recordRun(state: QueryTabsState, id: string, run: QueryTabRun): QueryTabsState {
            const tab = findTab(state, id);
            const kept = tab && tab.lastRun && tab.lastRun.saved;
            const next = typeof run.saved === 'undefined' && kept ? Object.assign({}, run, { saved: kept }) : run;
            return update(state, id, { lastRun: next, dirty: false });
        }

        function indexOf(state: QueryTabsState, id: string): number {
            for (let i = 0; i < state.tabs.length; i++) {
                if (state.tabs[i].id === id) {
                    return i;
                }
            }
            return -1;
        }

        /**
         * A store over one storage key, kept in two places. This browser page's working copy lives in `session`
         * (sessionStorage), so two pages open on the same repository keep their own tabs across a refresh; the latest
         * state any page wrote lives in `local` (localStorage) and seeds a page that has no working copy yet (a new
         * browser tab, or the browser restarted). Reading a bad or missing value gives `initial` (or one empty tab).
         * Storage failures (private mode, quota) are ignored: the state then lives in memory for this page.
         */
        export function createStore(local: StorageLike, session: StorageLike, key: string,
                                    initial?: QueryTabsState): Store {
            let state: QueryTabsState = null;
            const listeners: ((state: QueryTabsState) => void)[] = [];
            function read(storage: StorageLike): QueryTabsState {
                try {
                    return storage ? parseState(storage.getItem(key)) : null;
                } catch (error) {
                    return null;
                }
            }
            state = read(session) || read(local);
            let seeded = false;
            if (!state) {
                state = initial || emptyState();
                seeded = true;
            }
            function write(storage: StorageLike, text: string): void {
                if (!storage) {
                    return;
                }
                try {
                    storage.setItem(key, text);
                } catch (error) {
                    // Storage unavailable: keep the state for this page only.
                }
            }
            function persist(): void {
                const text = serializeState(state);
                write(session, text);
                write(local, text);
            }
            // The page's working copy exists from the start, so a refresh shows this page's tabs, not the latest
            // tabs another page wrote.
            if (seeded || !read(session)) {
                persist();
            }
            return {
                get: function() {
                    return state;
                },
                set: function(next: QueryTabsState) {
                    if (!next || next === state) {
                        return;
                    }
                    state = next;
                    persist();
                    listeners.slice().forEach(listener => listener(state));
                },
                subscribe: function(listener: (state: QueryTabsState) => void) {
                    listeners.push(listener);
                    return function() {
                        const index = listeners.indexOf(listener);
                        if (index >= 0) {
                            listeners.splice(index, 1);
                        }
                    };
                }
            };
        }

        // ------------------------------------------------------------------ the tab row (DOM)

        export interface TabRowCallbacks {
            onSelect(id: string): void;
            onClose(id: string): void;
            onNew(): void;
            /** Whether that tab's query has a request out right now (the page knows; the state does not). */
            isRunning(id: string): boolean;
        }

        /** The same strokes as the page's action icons (workbenchViews.ts actionIconPath), 24x24 stroke paths. */
        const ICONS: { [name: string]: string } = {
            add: 'M12 5v14M5 12h14',
            close: 'm6 6 12 12M18 6 6 18',
            more: 'M6 12h.01M12 12h.01M18 12h.01',
            saved: 'M6 4h12v16l-6-3-6 3V4Z'
        };
        const SVG_NS = 'http://www.w3.org/2000/svg';

        function icon(doc: Document, name: string, className: string): Element {
            const svg = doc.createElementNS(SVG_NS, 'svg');
            svg.setAttribute('class', 'workbench-action-icon workbench-action-icon--' + name + ' ' + className);
            svg.setAttribute('viewBox', '0 0 24 24');
            svg.setAttribute('width', '16');
            svg.setAttribute('height', '16');
            svg.setAttribute('focusable', 'false');
            svg.setAttribute('aria-hidden', 'true');
            const path = doc.createElementNS(SVG_NS, 'path');
            path.setAttribute('d', ICONS[name] || '');
            svg.appendChild(path);
            return svg;
        }

        function element(doc: Document, tag: string, className?: string, text?: string): HTMLElement {
            const node = doc.createElement(tag);
            if (className) {
                node.className = className;
            }
            if (text !== undefined) {
                node.textContent = text;
            }
            return node;
        }

        function clearChildren(node: Element): void {
            while (node.children && node.children.length) {
                node.removeChild(node.children[0]);
            }
        }

        function formatCount(run: QueryTabRun): string {
            const count = run.total !== null && run.total !== undefined ? run.total : run.rowCount;
            if (count === null || count === undefined) {
                return '';
            }
            const format: any = (<any>workbench).format;
            return format && typeof format.count === 'function' ? format.count(count) : String(count);
        }

        /** What a tab's status element shows: a spinner while running, else the last run's badge or dot. */
        function statusElement(doc: Document, tab: QueryTab, running: boolean): HTMLElement {
            if (running) {
                const spinner = element(doc, 'span', 'query-tabs__spinner');
                spinner.setAttribute('role', 'img');
                spinner.setAttribute('aria-label', 'Running');
                spinner.title = 'Running';
                return spinner;
            }
            const run = tab.lastRun;
            if (!run) {
                return null;
            }
            if (run.status === 'error') {
                const dot = element(doc, 'span', 'query-tabs__dot query-tabs__dot--error');
                dot.setAttribute('role', 'img');
                dot.setAttribute('aria-label', 'The last run failed');
                dot.title = 'The last run failed';
                return dot;
            }
            if (run.status === 'ready') {
                const ready = element(doc, 'span', 'query-tabs__dot query-tabs__dot--ready');
                ready.setAttribute('role', 'img');
                ready.setAttribute('aria-label', 'Finished; open the tab to see the result');
                ready.title = 'Finished; open the tab to see the result';
                return ready;
            }
            const count = formatCount(run);
            if (!count) {
                return null;
            }
            const badge = element(doc, 'span', 'query-tabs__badge', count);
            badge.title = count + ' rows';
            return badge;
        }

        function tabButton(doc: Document, tab: QueryTab, active: boolean, running: boolean,
                           callbacks: TabRowCallbacks): HTMLElement {
            const title = titleOf(tab);
            const button = element(doc, 'button', 'query-tabs__tab' + (tab.dirty ? ' is-dirty' : ''));
            button.setAttribute('type', 'button');
            button.setAttribute('role', 'tab');
            button.setAttribute('data-tab-id', tab.id);
            button.setAttribute('aria-selected', active ? 'true' : 'false');
            button.tabIndex = active ? 0 : -1;
            button.title = title + (tab.saved ? ' · saved query' : '') + (tab.dirty ? ' · edited since the last run' : '');
            if (tab.saved) {
                const mark = element(doc, 'span', 'query-tabs__saved');
                mark.appendChild(icon(doc, 'saved', 'query-tabs__saved-icon'));
                button.appendChild(mark);
            }
            const label = element(doc, 'span',
                'query-tabs__title' + (isDerivedTitle(tab) ? ' query-tabs__title--derived' : ''), title);
            button.appendChild(label);
            const status = statusElement(doc, tab, running);
            if (status) {
                button.appendChild(status);
            }
            const close = element(doc, 'span', 'query-tabs__close');
            close.setAttribute('role', 'button');
            close.setAttribute('aria-label', 'Close ' + title);
            close.title = tab.dirty ? 'Edited since the last run · Close' : 'Close';
            close.appendChild(icon(doc, 'close', 'query-tabs__close-icon'));
            close.appendChild(element(doc, 'span', 'query-tabs__dirty'));
            close.addEventListener('click', function(event: Event) {
                stop(event);
                callbacks.onClose(tab.id);
            });
            button.appendChild(close);
            button.addEventListener('click', function() {
                callbacks.onSelect(tab.id);
            });
            // Middle click closes, as in a browser.
            button.addEventListener('auxclick', function(event: MouseEvent) {
                if (event.button === 1) {
                    stop(event);
                    callbacks.onClose(tab.id);
                }
            });
            return button;
        }

        /** Swallow a click or key so the tab under the control is not selected as well (DOM fakes may lack both). */
        function stop(event: Event): void {
            if (event && typeof event.stopPropagation === 'function') {
                event.stopPropagation();
            }
            if (event && typeof event.preventDefault === 'function') {
                event.preventDefault();
            }
        }

        function tabIdOf(node: EventTarget): string {
            const tab = node && (<HTMLElement>node).closest ? <HTMLElement>(<HTMLElement>node).closest('[role="tab"]') : null;
            return tab ? tab.getAttribute('data-tab-id') || '' : '';
        }

        /** Arrow keys move between tabs and select; Delete or Backspace closes the focused tab. */
        function onStripKeydown(event: KeyboardEvent, state: QueryTabsState, callbacks: TabRowCallbacks): void {
            const id = tabIdOf(event.target);
            if (!id) {
                return;
            }
            let index = -1;
            for (let i = 0; i < state.tabs.length; i++) {
                if (state.tabs[i].id === id) {
                    index = i;
                }
            }
            if (index < 0) {
                return;
            }
            let next = -1;
            if (event.key === 'ArrowRight') {
                next = (index + 1) % state.tabs.length;
            } else if (event.key === 'ArrowLeft') {
                next = (index - 1 + state.tabs.length) % state.tabs.length;
            } else if (event.key === 'Home') {
                next = 0;
            } else if (event.key === 'End') {
                next = state.tabs.length - 1;
            } else if (event.key === 'Delete' || event.key === 'Backspace') {
                stop(event);
                callbacks.onClose(id);
                return;
            }
            if (next >= 0) {
                stop(event);
                callbacks.onSelect(state.tabs[next].id);
            }
        }

        function menuRow(doc: Document, tab: QueryTab, active: boolean, running: boolean,
                         callbacks: TabRowCallbacks): HTMLElement {
            const row = element(doc, 'li', 'query-tabs__menu-row' + (active ? ' is-active' : ''));
            const select = element(doc, 'button', 'query-tabs__menu-select');
            select.setAttribute('type', 'button');
            select.setAttribute('role', 'menuitemradio');
            select.setAttribute('aria-checked', active ? 'true' : 'false');
            if (tab.saved) {
                select.appendChild(icon(doc, 'saved', 'query-tabs__saved-icon'));
            }
            select.appendChild(element(doc, 'span',
                'query-tabs__title' + (isDerivedTitle(tab) ? ' query-tabs__title--derived' : ''), titleOf(tab)));
            const status = statusElement(doc, tab, running);
            if (status) {
                select.appendChild(status);
            }
            select.appendChild(element(doc, 'span', 'query-tabs__menu-meta', runText(tab, running)));
            select.addEventListener('click', function() {
                const popover: any = (<any>workbench).popover;
                if (popover && typeof popover.closeAll === 'function') {
                    popover.closeAll();
                }
                callbacks.onSelect(tab.id);
            });
            row.appendChild(select);
            const close = element(doc, 'button', 'query-tabs__menu-close');
            close.setAttribute('type', 'button');
            close.setAttribute('aria-label', 'Close ' + titleOf(tab));
            close.title = 'Close';
            close.appendChild(icon(doc, 'close', 'query-tabs__close-icon'));
            close.addEventListener('click', function(event: Event) {
                stop(event);
                callbacks.onClose(tab.id);
            });
            row.appendChild(close);
            return row;
        }

        /** A short description of the last run for the menu: '17 rows', 'Running', 'Failed', 'Not run yet'. */
        export function runText(tab: QueryTab, running: boolean): string {
            if (running) {
                return 'Running';
            }
            const run = tab.lastRun;
            if (!run) {
                return 'Not run yet';
            }
            if (run.status === 'error') {
                return 'Failed';
            }
            if (run.status === 'ready') {
                return 'Finished';
            }
            const count = formatCount(run);
            const rows = count ? count + (count === '1' ? ' row' : ' rows') : 'Complete';
            return rows + (tab.dirty ? ' · edited since' : '');
        }

        /**
         * Rebuild the tab row inside `container`: the scrolling strip of tabs and the "+" button, then the "⋯"
         * button whose popover lists every open query. Called on every state change; the DOM is small.
         */
        export function renderTabRow(container: HTMLElement, state: QueryTabsState, callbacks: TabRowCallbacks): void {
            if (!container) {
                return;
            }
            const doc = container.ownerDocument;
            clearChildren(container);
            const strip = element(doc, 'div', 'query-tabs__strip');
            strip.setAttribute('role', 'tablist');
            strip.setAttribute('aria-label', 'Open queries');
            state.tabs.forEach(function(tab) {
                strip.appendChild(tabButton(doc, tab, tab.id === state.activeId, callbacks.isRunning(tab.id), callbacks));
            });
            const add = element(doc, 'button', 'query-tabs__new');
            add.setAttribute('type', 'button');
            add.setAttribute('aria-label', 'New query');
            const full = state.tabs.length >= MAX_TABS;
            add.title = full ? 'Close a query to open another (' + MAX_TABS + ' at most)' : 'New query';
            (<HTMLButtonElement>add).disabled = full;
            add.appendChild(icon(doc, 'add', 'query-tabs__new-icon'));
            add.addEventListener('click', function() {
                callbacks.onNew();
            });
            strip.appendChild(add);
            strip.addEventListener('keydown', function(event: KeyboardEvent) {
                onStripKeydown(event, state, callbacks);
            });
            container.appendChild(strip);

            const menu = element(doc, 'div', 'query-tabs__menu');
            const menuButton = element(doc, 'button', 'query-tabs__menu-button');
            menuButton.setAttribute('type', 'button');
            menuButton.setAttribute('aria-label', 'All open queries');
            menuButton.setAttribute('aria-haspopup', 'true');
            menuButton.setAttribute('aria-expanded', 'false');
            menuButton.title = 'All open queries';
            menuButton.appendChild(icon(doc, 'more', 'query-tabs__menu-icon'));
            const panel = element(doc, 'div', 'query-tabs__menu-panel workbench-popover');
            panel.hidden = true;
            const heading = element(doc, 'div', 'query-tabs__menu-heading', 'Open queries');
            panel.appendChild(heading);
            const list = element(doc, 'ul', 'query-tabs__menu-list');
            list.setAttribute('role', 'menu');
            state.tabs.forEach(function(tab) {
                list.appendChild(menuRow(doc, tab, tab.id === state.activeId, callbacks.isRunning(tab.id), callbacks));
            });
            panel.appendChild(list);
            const actions = element(doc, 'div', 'query-tabs__menu-actions');
            const closeOthers = element(doc, 'button', 'query-tabs__menu-action', 'Close others');
            closeOthers.setAttribute('type', 'button');
            (<HTMLButtonElement>closeOthers).disabled = state.tabs.length < 2;
            closeOthers.addEventListener('click', function() {
                state.tabs.forEach(function(tab) {
                    if (tab.id !== state.activeId) {
                        callbacks.onClose(tab.id);
                    }
                });
            });
            const closeAll = element(doc, 'button', 'query-tabs__menu-action', 'Close all');
            closeAll.setAttribute('type', 'button');
            closeAll.addEventListener('click', function() {
                state.tabs.forEach(function(tab) {
                    callbacks.onClose(tab.id);
                });
            });
            actions.appendChild(closeOthers);
            actions.appendChild(closeAll);
            actions.appendChild(element(doc, 'span', 'query-tabs__menu-hint', 'Open queries are kept for your next visit'));
            panel.appendChild(actions);
            menu.appendChild(menuButton);
            menu.appendChild(panel);
            container.appendChild(menu);
            const popover: any = (<any>workbench).popover;
            if (popover && typeof popover.bind === 'function') {
                popover.bind(menuButton, panel);
            }
        }
    }
}
